body:
Hello!

I saw that the app previously had a bug (issue #2526). I created a test (based on that version of the app) to help ensuring that the issue does not happen again. In other words, the test could be used for regression testing.

Would it be helpful if I contributed this test to your codebase? I’d be happy to open a pull request for the latest version, integrating the test with your existing test infrastructure.

Additionally, I’ve created similar regression tests for 13 other issues in the repository that I would also be happy to integrate if it would be helpful.

You can find the script for issue #2526 below:
```


import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;

import android.content.Context;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.content.pm.ResolveInfo;
import android.os.RemoteException;

import static androidx.test.core.app.ApplicationProvider.getApplicationContext;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;

import androidx.test.filters.SdkSuppress;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.uiautomator.By;
import androidx.test.uiautomator.UiDevice;
import androidx.test.uiautomator.UiObject2;
import androidx.test.uiautomator.Until;

import java.util.concurrent.TimeUnit;

import static org.hamcrest.CoreMatchers.notNullValue;
import static org.junit.Assert.assertThat;
import static org.junit.Assert.assertTrue;

/**
 * Regression test for FTP server state inconsistency in Amaze File Manager.
 * Ensures the UI correctly reflects the server status after interaction through notification.
 */
@RunWith(AndroidJUnit4.class)
@SdkSuppress(minSdkVersion = 18)
public class Amaze_FTP_Server_UI_Status_Test {

    private static final String APP_PACKAGE_NAME = "com.amaze.filemanager";
    private static final int LAUNCH_TIMEOUT = 5000;

    private UiDevice mDevice;

    @Before
    public void startMainActivityFromHomeScreen() {
        mDevice = UiDevice.getInstance(getInstrumentation());
        mDevice.pressHome();

        final String launcherPackage = getLauncherPackageName();
        assertThat(launcherPackage, notNullValue());
        mDevice.wait(Until.hasObject(By.pkg(launcherPackage).depth(0)), LAUNCH_TIMEOUT);

        Context context = getApplicationContext();
        final Intent intent = context.getPackageManager()
                .getLaunchIntentForPackage(APP_PACKAGE_NAME);
        intent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TASK);
        context.startActivity(intent);

        mDevice.wait(Until.hasObject(By.pkg(APP_PACKAGE_NAME).depth(0)), LAUNCH_TIMEOUT);
    }

    @Test
    public void testFtpServerStatusAfterNotificationInteraction() throws InterruptedException, RemoteException {
        mDevice = UiDevice.getInstance(getInstrumentation());

        // Grant permissions if prompted
        UiObject2 allowButton = mDevice.wait(Until.findObject(By.text("ALLOW")), 2000);
        if (allowButton != null) {
            allowButton.click();
            TimeUnit.MILLISECONDS.sleep(2000);
        }

        // Dismiss any overlays
        mDevice.click(100, 100);
        TimeUnit.MILLISECONDS.sleep(2000);

        // Scroll down to FTP option
        mDevice.swipe(100, 1800, 100, 500, 20);
        TimeUnit.MILLISECONDS.sleep(2000);

        // Start FTP server
        UiObject2 ftpServerOption = mDevice.wait(Until.findObject(By.text("FTP Server")), 2000);
        ftpServerOption.click();

        UiObject2 startFtpButton = mDevice.wait(Until.findObject(By.text("START")), 2000);
        startFtpButton.click();

        // Confirm any storage access prompt
        UiObject2 okButton = mDevice.wait(Until.findObject(By.text("OK")), 2000);
        if (okButton != null) {
            okButton.click();
            TimeUnit.MILLISECONDS.sleep(2000);

            // Confirm SD card selection
            mDevice.click(100, 100);
            TimeUnit.MILLISECONDS.sleep(2000);
            UiObject2 sdcardOption = mDevice.wait(Until.findObject(By.text("SDCARD")), 2000);
            sdcardOption.click();

            UiObject2 selectButton = mDevice.wait(Until.findObject(By.text("SELECT")), 2000);
            selectButton.click();
        }

        TimeUnit.MILLISECONDS.sleep(2000);

        // Simulate interaction through the notification tray
        mDevice.pressHome();
        mDevice.waitForIdle();

        // Pull down notification panel
        mDevice.swipe(540, 0, 540, 1800, 20);

        UiObject2 stopFtpButton = mDevice.wait(Until.findObject(By.text("STOP")), 2000);
        stopFtpButton.click();
        TimeUnit.MILLISECONDS.sleep(2000);

        // Re-open the app from recent apps
        mDevice.pressRecentApps();
        TimeUnit.MILLISECONDS.sleep(2000);

        UiObject2 amazeAppIcon = mDevice.wait(Until.findObject(By.desc("Amaze")), 2000);
        amazeAppIcon.click();
        TimeUnit.MILLISECONDS.sleep(2000);

        // === ASSERTIONS ===

        // Check for text indicating FTP server status
        UiObject2 ftpStatusLabel = mDevice.findObject(By.textContains("Secure Connection"));
        assertTrue("FTP status label should be present", ftpStatusLabel != null);

        // Get the current FTP status label and button states
        UiObject2 ftpStatusText = mDevice.findObject(By.res("com.amaze.filemanager:id/text_view_ftp_status"));
        UiObject2 startStopButton = mDevice.findObject(By.res("com.amaze.filemanager:id/startStopButton"));

        // Ensure that the status text and button state are consistent
        Assert.assertFalse(
            "FTP status text should still show 'Secure Connection' and button should say 'STOP'",
            ftpStatusText.getText().equals("Secure Connection") &&
            startStopButton.getText().equals("STOP")
        );
    }

    /**
     * Uses PackageManager to determine the current device launcher app.
     */
    private String getLauncherPackageName() {
        Intent intent = new Intent(Intent.ACTION_MAIN);
        intent.addCategory(Intent.CATEGORY_HOME);
        PackageManager pm = getApplicationContext().getPackageManager();
        ResolveInfo resolveInfo = pm.resolveActivity(intent, PackageManager.MATCH_DEFAULT_ONLY);
        return resolveInfo.activityInfo.packageName;
    }
}


